<template><header class="topbar"><div class="nav"><router-link class="brand" to="/">VORA</router-link><nav><router-link to="/">Shop</router-link><a href="#" @click.prevent="goCategories">Categories</a><a href="#support">Support</a></nav><div class="nav-tools"><router-link to="/shop" aria-label="Search">⌕</router-link><router-link to="/cart" class="cart">Cart <span>{{count}}</span></router-link></div></div></header><main><router-view/></main><footer id="support"><div><strong>VORA</strong><p>Engineered for Excellence.</p></div><div><b>Shop</b><a>Customer Service</a><a>Warranty Info</a><a>Returns</a></div><div><b>Company</b><a>About</a><a>Policies</a><a>Contact</a></div><small>© 2026 VORA Electronics. All rights reserved.</small></footer></template>
